module LIFObuffer(
    input [3:0] dataIn, 
    input RW, 
    input EN, 
    input Rst, 
    input Clk,
    output EMPTY, 
    output FULL, 
    output [3:0] dataOut
);
// Parameters
parameter EMPTY_STATE = 1'b0;
parameter DATA_PRESENT = 1'b1;
parameter BUFFER_FULL = 1'b1;
// Internal signals
reg [3:0] SP;
reg [3:0] stack_mem [3:0];
// Combinational logic
assign EMPTY = ((SP == 4'h4) && (stack_mem[SP][3] == 0)) ? 1 : 0;
assign FULL = ((SP == 4'h0) && (stack_mem[SP][3] == 1)) ? 1 : 0;
// Sequential logic
always @(posedge Clk) begin
    if(EN==1) begin
        if(Rst==1)begin
            SP <= 4'd4;
            stack_mem[0] <= 4'd0;
            stack_mem[1] <= 4'd0;
            stack_mem[2] <= 4'd0;
            stack_mem[3] <= 4'd0;
        end else begin
            case({RW, SP})
                {1'b0, 4'h4}: begin
                    stack_mem[SP]<=dataIn;
                    SP<=SP-1;
                end
                {1'b1, 4'h0}: begin
                    SP<=SP+1;
                    stack_mem[SP]<={4{1'b0}};
                end
                default: begin
                    SP<=SP;
                end
            endcase
        end
    end
end
endmodule
